use std::{fs,process::{Command,Stdio},io::{BufRead,BufReader}};use serde_json::json;
fn main(){let r="/tmp/zopro-poseidon-fused-dot";let binary=format!("{r}/native/fused-sdk");let out=Command::new("nm").args(["-S","--size-sort",&binary]).output().unwrap();assert!(out.status.success());let symbols=String::from_utf8(out.stdout).unwrap();let rows:Vec<_>=symbols.lines().filter(|s|s.contains("3dot3dot")).collect();assert_eq!(rows.len(),1);let fields:Vec<_>=rows[0].split_whitespace().collect();let size=u64::from_str_radix(fields[1],16).unwrap();let symbol=fields[3];let out=Command::new("objdump").args(["-d",&format!("--disassemble={symbol}"),&binary]).output().unwrap();assert!(out.status.success());fs::write(format!("{r}/dot.asm.txt"),out.stdout).unwrap();fs::write(format!("{r}/dot-symbol.txt"),rows[0]).unwrap();let mut child=Command::new("objdump").args(["-d","--demangle",&binary]).stdout(Stdio::piped()).spawn().unwrap();let mut calls=Vec::new();for line in BufReader::new(child.stdout.take().unwrap()).lines(){let line=line.unwrap();if line.contains("call")&&line.contains("sparse_poseidon::dot::dot"){calls.push(line);}}assert!(child.wait().unwrap().success());assert!(!calls.is_empty());fs::write(format!("{r}/dot-call-sites.txt"),calls.join("\n")).unwrap();fs::write(format!("{r}/codegen-audit.json"),serde_json::to_vec_pretty(&json!({"binary":binary,"dot_symbol":symbol,"dot_body_bytes":size,"direct_call_sites_in_ELF":calls.len(),"dot_is_outlined":true,"dynamic_call_count_measured":false,"profiles_collected":false,"regression_cause_established":false,"next_source_hypothesis":"Use the same field fused primitive at explicit fixed-width3 call sites instead of a generic outlined slice helper. Audit compiler output and qualify any distinct source version; no unchanged screen rerun or claim of a proven speedup."})).unwrap()).unwrap();println!("Dot helper{size}bytes/{}staticdirectcalls; no causal timing attribution",calls.len());}
